7	/** Tax is computed per line on the pre-discount line amount, each line rounded on its own. */
8	export function buildInvoice(lines: Line[], discount?: Discount): Invoice {
9	  const groups = groupLines(lines);
10	  const subtotal = groups.reduce((s, g) => s + g.subtotal, 0);
11	  const off = discountAmount(subtotal, discount);
12	  const tax = lines.reduce((s, l) => s + mulBps(lineTotal(l.unit, l.qty), l.taxBps), 0);
13	  const shipping = shippingFor(subtotal - off, lines.length);
14	  return { groups, subtotal, discount: off, tax, shipping, total: subtotal - off + tax + shipping };
15	}

